static int ft_root=-1,ft_store=-1;
static char ft_proxy[129];
static unsigned char ft_store_key[32];
static const uint64_t ft_max_bytes=20ULL*1024*1024*1024;
static bool store_write_all(int fd,const void *data,size_t length){const unsigned char*p=data;while(length){ssize_t n=write(fd,p,length);if(n<0&&errno==EINTR)continue;if(n<=0)return false;p+=n;length-=(size_t)n;}return true;}
static bool store_send_all(int fd,const void *data,size_t length){const unsigned char*p=data;while(length){ssize_t n=send(fd,p,length,0);if(n<0&&errno==EINTR)continue;if(n<=0)return false;p+=n;length-=(size_t)n;}return true;}
static bool store_header(const char *headers,const char *name,char *value,size_t cap){size_t size=strlen(name);const char *line=strstr(headers,"\r\n");while(line){line+=2;const char *end=strstr(line,"\r\n");size_t n=end?(size_t)(end-line):strlen(line);if(n>size&&line[size]==':'&&!strncasecmp(line,name,size)){const char*p=line+size+1;while(p<line+n&&(*p==' '||*p=='\t'))p++;size_t len=(size_t)(line+n-p);if(len>=cap)return false;memcpy(value,p,len);value[len]=0;return true;}line=end;}if(cap)value[0]=0;return false;}
static cJSON *store_json_fd(int fd,uint64_t length){if(length>1024*1024)return NULL;char*body=calloc(1,(size_t)length+1);if(!body)return NULL;size_t got=0;while(got<length){ssize_t n=recv(fd,body+got,(size_t)length-got,0);if(n<0&&errno==EINTR)continue;if(n<=0){free(body);return NULL;}got+=(size_t)n;}cJSON*value=length?cJSON_ParseWithLength(body,(size_t)length):cJSON_CreateObject();free(body);if(!cJSON_IsObject(value)){cJSON_Delete(value);return NULL;}return value;}
static void store_reply(int fd,int status,const char *code,const char *message,cJSON *data){cJSON*envelope=cJSON_CreateObject();cJSON_AddStringToObject(envelope,"code",code);cJSON_AddStringToObject(envelope,"message",message);if(data)cJSON_AddItemToObject(envelope,"data",data);else cJSON_AddNullToObject(envelope,"data");char*text=cJSON_PrintUnformatted(envelope);if(text){char header[256];int n=snprintf(header,sizeof(header),"HTTP/1.1 %d %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n",status,status<300?"OK":"Error",strlen(text));store_send_all(fd,header,(size_t)n);store_send_all(fd,text,strlen(text));free(text);}cJSON_Delete(envelope);}
static cJSON *store_load(int dir,const char *name){int fd=openat(dir,name,O_RDONLY|O_NOFOLLOW);if(fd<0)return NULL;struct stat st;if(fstat(fd,&st)||st.st_size<0||st.st_size>8*1024*1024){close(fd);return NULL;}size_t length=(size_t)st.st_size;char*text=calloc(1,length+1);if(!text){close(fd);return NULL;}size_t got=0;while(got<length){ssize_t n=read(fd,text+got,length-got);if(n<0&&errno==EINTR)continue;if(n<=0)break;got+=(size_t)n;}close(fd);cJSON*json=got==length?cJSON_ParseWithLength(text,length):NULL;free(text);return json;}
static bool store_save(int dir,const char *name,cJSON *json){char tmp[96],random[17];if(!ft_random_hex(random,8))return false;snprintf(tmp,sizeof(tmp),".%s.%s.tmp",name,random);char*text=cJSON_PrintUnformatted(json);if(!text)return false;int fd=openat(dir,tmp,O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600);bool ok=fd>=0&&store_write_all(fd,text,strlen(text))&&fsync(fd)==0;free(text);if(fd>=0&&close(fd)!=0)ok=false;if(ok)ok=renameat(dir,tmp,dir,name)==0&&fsync(dir)==0;if(!ok)unlinkat(dir,tmp,0);return ok;}
static bool store_identity(const char *s){size_t n=strlen(s);if(!n||n>128)return false;for(size_t i=0;i<n;i++)if(!((s[i]>='a'&&s[i]<='z')||(s[i]>='A'&&s[i]<='Z')||(s[i]>='0'&&s[i]<='9')||s[i]=='-'||s[i]=='_'))return false;return true;}
static bool store_path_valid(const char *path){size_t length=strlen(path);if(!length||length>1024||path[0]=='/'||path[length-1]=='/'||strstr(path,"//")||strchr(path,'\\'))return false;char copy[1025];memcpy(copy,path,length+1);char *save=NULL;for(char*p=strtok_r(copy,"/",&save);p;p=strtok_r(NULL,"/",&save)){if(!strcmp(p,".")||!strcmp(p,"..")||!strcmp(p,".se9-transfers")||!strcmp(p,".uploading")||strlen(p)>255)return false;for(const unsigned char*q=(unsigned char*)p;*q;q++)if(*q<32||*q==127)return false;}return true;}
static int store_parent(const char *path,bool create,char leaf[256]){if(!store_path_valid(path))return -1;char copy[1025];snprintf(copy,sizeof(copy),"%s",path);char*last=strrchr(copy,'/');if(last){*last=0;snprintf(leaf,256,"%s",last+1);}else{snprintf(leaf,256,"%s",path);copy[0]=0;}int current=dup(ft_root);if(current<0)return -1;char*save=NULL;for(char*p=strtok_r(copy,"/",&save);p;p=strtok_r(NULL,"/",&save)){int next=openat(current,p,O_RDONLY|O_DIRECTORY|O_NOFOLLOW);if(next<0&&errno==ENOENT&&create){if(mkdirat(current,p,0750)!=0&&errno!=EEXIST){close(current);return -1;}next=openat(current,p,O_RDONLY|O_DIRECTORY|O_NOFOLLOW);}close(current);if(next<0)return -1;current=next;}return current;}
static bool store_copy(int input,int output){unsigned char buffer[65536];for(;;){ssize_t n=read(input,buffer,sizeof(buffer));if(n<0&&errno==EINTR)continue;if(n<0)return false;if(n==0)return true;if(!store_write_all(output,buffer,(size_t)n))return false;}}
static bool store_same(const struct stat*a,const struct stat*b){if(a->st_dev!=b->st_dev||a->st_ino!=b->st_ino||a->st_size!=b->st_size)return false;
#ifdef __APPLE__
 return a->st_mtimespec.tv_sec==b->st_mtimespec.tv_sec&&a->st_mtimespec.tv_nsec==b->st_mtimespec.tv_nsec&&a->st_ctimespec.tv_sec==b->st_ctimespec.tv_sec&&a->st_ctimespec.tv_nsec==b->st_ctimespec.tv_nsec;
#else
 return a->st_mtim.tv_sec==b->st_mtim.tv_sec&&a->st_mtim.tv_nsec==b->st_mtim.tv_nsec&&a->st_ctim.tv_sec==b->st_ctim.tv_sec&&a->st_ctim.tv_nsec==b->st_ctim.tv_nsec;
#endif
}
static void store_string(cJSON*m,const char*name,const char*value){cJSON_DeleteItemFromObjectCaseSensitive(m,name);cJSON_AddStringToObject(m,name,value);}
static void store_uint(cJSON*m,const char*name,uint64_t value){cJSON_DeleteItemFromObjectCaseSensitive(m,name);ft_number(m,name,value);}
static uint64_t store_num(cJSON*m,const char*name){uint64_t n=0;(void)ft_u64(m,name,&n);return n;}
static bool store_token(const char*id,char output[65]){unsigned char raw[32];unsigned int length=0;if(!HMAC(EVP_sha256(),ft_store_key,32,(const unsigned char*)id,strlen(id),raw,&length)||length!=32)return false;for(size_t i=0;i<32;i++)snprintf(output+i*2,3,"%02x",raw[i]);return true;}
static cJSON*store_view(cJSON*m,uint64_t cursor,bool with_token){cJSON*v=cJSON_CreateObject();const char*names[]={"transferId","direction","path","size","sha256","sourceVersion","state","blockBytes","epoch","expiresAt"};for(size_t i=0;i<sizeof(names)/sizeof(names[0]);i++)cJSON_AddStringToObject(v,names[i],ft_string(m,names[i]));cJSON*blocks=cJSON_GetObjectItemCaseSensitive(m,"blocks");uint64_t size=store_num(m,"size"),durable=0;int count=cJSON_GetArraySize(blocks);for(int i=0;i<count;i++)if(cJSON_IsString(cJSON_GetArrayItem(blocks,i))){uint64_t len=size-(uint64_t)i*SE9_FT_BLOCK;if(len>SE9_FT_BLOCK)len=SE9_FT_BLOCK;durable+=len;}ft_number(v,"durableBytes",durable);ft_number(v,"maxInFlightBytes",2*SE9_FT_BLOCK);cJSON*ranges=cJSON_AddArrayToObject(v,"committedRanges");uint64_t index=cursor;int used=0;while(index<(uint64_t)count&&used<64){if(!cJSON_IsString(cJSON_GetArrayItem(blocks,(int)index))){index++;continue;}uint64_t first=index;while(index<(uint64_t)count&&cJSON_IsString(cJSON_GetArrayItem(blocks,(int)index)))index++;cJSON*range=cJSON_CreateObject();ft_number(range,"firstBlock",first);ft_number(range,"lastBlock",index-1);cJSON_AddItemToArray(ranges,range);used++;}if(index<(uint64_t)count)ft_number(v,"cursor",index);if(with_token){char token[65];if(store_token(ft_string(m,"transferId"),token))cJSON_AddStringToObject(v,"resumeToken",token);}return v;}
static void store_remove_task(const char*name){int dir=openat(ft_store,name,O_RDONLY|O_DIRECTORY|O_NOFOLLOW);if(dir<0)return;int lock=openat(dir,"task.lock",O_RDWR|O_CREAT|O_NOFOLLOW,0600);if(lock<0||flock(lock,LOCK_EX|LOCK_NB)!=0){if(lock>=0)close(lock);close(dir);return;}cJSON*m=store_load(dir,"manifest.json");struct stat entry_stat;bool orphan=!m&&fstat(dir,&entry_stat)==0&&entry_stat.st_mtime<time(NULL)-86400;bool expired=orphan||(m&&store_num(m,"expiresAt")<(uint64_t)time(NULL));cJSON_Delete(m);if(expired){DIR*d=fdopendir(dup(dir));if(d){struct dirent*entry;while((entry=readdir(d)))if(strcmp(entry->d_name,".")&&strcmp(entry->d_name,".."))unlinkat(dir,entry->d_name,0);closedir(d);}unlinkat(ft_store,name,AT_REMOVEDIR);}flock(lock,LOCK_UN);close(lock);close(dir);}
bool se9_transfer_init(const char *root,const char *proxy_secret){if(strlen(proxy_secret)>=sizeof(ft_proxy))return false;snprintf(ft_proxy,sizeof(ft_proxy),"%s",proxy_secret);ft_root=open(root,O_RDONLY|O_DIRECTORY|O_NOFOLLOW);if(ft_root<0)return false;if(mkdirat(ft_root,".se9-transfers",0700)!=0&&errno!=EEXIST)return false;ft_store=openat(ft_root,".se9-transfers",O_RDONLY|O_DIRECTORY|O_NOFOLLOW);if(ft_store<0)return false;int lock=openat(ft_store,"init.lock",O_RDWR|O_CREAT|O_NOFOLLOW,0600);if(lock<0||flock(lock,LOCK_EX)!=0){if(lock>=0)close(lock);return false;}int key=openat(ft_store,"store.key",O_RDONLY|O_NOFOLLOW);bool ok=true;if(key>=0){ok=read(key,ft_store_key,32)==32;close(key);}else if(errno==ENOENT){char random[65];ok=ft_random_hex(random,32);if(ok){for(size_t i=0;i<32;i++){char b[3]={random[i*2],random[i*2+1],0};ft_store_key[i]=(unsigned char)strtoul(b,NULL,16);}key=openat(ft_store,"store.key",O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600);ok=key>=0&&store_write_all(key,ft_store_key,32)&&fsync(key)==0;if(key>=0)close(key);if(ok)ok=fsync(ft_store)==0;}}else ok=false;flock(lock,LOCK_UN);close(lock);return ok;}
static void store_start(int fd,const char*user,const char*device,cJSON*in){const char*path=ft_string(in,"path"),*direction=ft_string(in,"direction"),*request=ft_string(in,"requestId"),*expected=ft_string(in,"sha256");uint64_t size=0;bool upload=!strcmp(direction,"upload");if(!store_path_valid(path)||!store_identity(request)||(!upload&&strcmp(direction,"download"))||(upload&&(!ft_u64(in,"size",&size)||size>ft_max_bytes||!ft_hex(expected,32)))||cJSON_IsTrue(cJSON_GetObjectItemCaseSensitive(in,"overwrite"))){store_reply(fd,400,"INVALID_TRANSFER","invalid transfer parameters",NULL);return;}
 char identity[512],id[33],key_hash[65];int n=snprintf(identity,sizeof(identity),"%s|%s|%s",user,device,request);if(n<0||(size_t)n>=sizeof(identity)||!ft_sha256(identity,(size_t)n,key_hash)){store_reply(fd,500,"IO_ERROR","identity failure",NULL);return;}memcpy(id,key_hash,32);id[32]=0;
 int init=openat(ft_store,"init.lock",O_RDWR|O_NOFOLLOW);if(init<0||flock(init,LOCK_EX)!=0){if(init>=0)close(init);store_reply(fd,500,"IO_ERROR","lock unavailable",NULL);return;}
 int dir=-1,lock=-1; cJSON*m=NULL;const char*error="IO_ERROR";int status=500;
 if(mkdirat(ft_store,id,0700)!=0&&errno!=EEXIST)goto fail;dir=openat(ft_store,id,O_RDONLY|O_DIRECTORY|O_NOFOLLOW);if(dir<0)goto fail;lock=openat(dir,"task.lock",O_RDWR|O_CREAT|O_NOFOLLOW,0600);if(lock<0||flock(lock,LOCK_EX)!=0)goto fail;
 m=store_load(dir,"manifest.json");if(m){if(strcmp(ft_string(m,"userId"),user)||strcmp(ft_string(m,"deviceId"),device)||strcmp(ft_string(m,"direction"),direction)||strcmp(ft_string(m,"path"),path)||(upload&&(store_num(m,"size")!=size||strcmp(ft_string(m,"sha256"),expected)))){error="REQUEST_CONFLICT";status=409;goto fail;}if(store_num(m,"expiresAt")<(uint64_t)time(NULL)){error="TRANSFER_EXPIRED";status=410;goto fail;}store_reply(fd,201,"0","success",store_view(m,0,true));goto done;}
 DIR*scan=fdopendir(dup(ft_store));unsigned int active=0;if(scan){struct dirent*e;while((e=readdir(scan))){if(!ft_hex(e->d_name,16)||!strcmp(e->d_name,id))continue;store_remove_task(e->d_name);int other=openat(ft_store,e->d_name,O_RDONLY|O_DIRECTORY|O_NOFOLLOW);if(other>=0){cJSON*v=store_load(other,"manifest.json");if(v&&strcmp(ft_string(v,"state"),"completed")&&strcmp(ft_string(v,"state"),"cancelled"))active++;cJSON_Delete(v);close(other);}}closedir(scan);}if(active>=2){error="QUOTA_EXCEEDED";status=429;goto fail;}
 char leaf[256];int parent=store_parent(path,upload,leaf);if(parent<0){error="PATH_DENIED";status=400;goto fail;}if(upload){struct stat target;if(fstatat(parent,leaf,&target,AT_SYMLINK_NOFOLLOW)==0){close(parent);error="FILE_EXISTS";status=409;goto fail;}if(errno!=ENOENT){close(parent);error="PATH_DENIED";status=400;goto fail;}}int input=-1;struct stat before={0};if(!upload){input=openat(parent,leaf,O_RDONLY|O_NOFOLLOW);if(input<0||fstat(input,&before)!=0||!S_ISREG(before.st_mode)||before.st_size<0){if(input>=0)close(input);close(parent);error="FILE_NOT_FOUND";status=404;goto fail;}size=(uint64_t)before.st_size;if(size>ft_max_bytes){close(input);close(parent);error="FILE_TOO_LARGE";status=413;goto fail;}}close(parent);
 struct statvfs fs;if(fstatvfs(ft_store,&fs)!=0||(uint64_t)fs.f_bavail*fs.f_frsize<size*(upload?2:1)+16*1024*1024){if(input>=0)close(input);error="NO_SPACE";status=507;goto fail;}
 char hash[65];if(upload)snprintf(hash,sizeof(hash),"%s",expected);else{int snapshot=openat(dir,"snapshot.tmp",O_WRONLY|O_CREAT|O_TRUNC|O_NOFOLLOW,0600);bool ok=snapshot>=0&&store_copy(input,snapshot)&&fsync(snapshot)==0;struct stat after;if(fstat(input,&after)!=0||!store_same(&before,&after))ok=false;close(input);if(snapshot>=0)close(snapshot);if(!ok){unlinkat(dir,"snapshot.tmp",0);error="SOURCE_CHANGED";status=409;goto fail;}if(renameat(dir,"snapshot.tmp",dir,"snapshot")!=0||fsync(dir)!=0)goto fail;snapshot=openat(dir,"snapshot",O_RDONLY|O_NOFOLLOW);ok=snapshot>=0&&ft_hash_fd(snapshot,hash);if(snapshot>=0)close(snapshot);if(!ok)goto fail;}
 m=cJSON_CreateObject();cJSON_AddStringToObject(m,"transferId",id);cJSON_AddStringToObject(m,"userId",user);cJSON_AddStringToObject(m,"deviceId",device);cJSON_AddStringToObject(m,"direction",direction);cJSON_AddStringToObject(m,"path",path);cJSON_AddStringToObject(m,"sha256",hash);cJSON_AddStringToObject(m,"sourceVersion",upload?"":hash);cJSON_AddStringToObject(m,"state","transferring");ft_number(m,"size",size);ft_number(m,"blockBytes",SE9_FT_BLOCK);ft_number(m,"epoch",1);ft_number(m,"expiresAt",(uint64_t)time(NULL)+86400);char token[65],token_hash[65];if(!store_token(id,token)||!ft_sha256(token,strlen(token),token_hash))goto fail;cJSON_AddStringToObject(m,"resumeTokenHash",token_hash);cJSON*blocks=cJSON_AddArrayToObject(m,"blocks");uint64_t count=(size+SE9_FT_BLOCK-1)/SE9_FT_BLOCK;for(uint64_t i=0;i<count;i++)cJSON_AddItemToArray(blocks,cJSON_CreateNull());if(!store_save(dir,"manifest.json",m)||fsync(ft_store)!=0)goto fail;store_reply(fd,201,"0","success",store_view(m,0,true));goto done;
fail:store_reply(fd,status,error,error,NULL);
done:cJSON_Delete(m);if(lock>=0){flock(lock,LOCK_UN);close(lock);}if(dir>=0)close(dir);flock(init,LOCK_UN);close(init);
}
static bool store_receive_block(int sock,int dir,const char*name,uint64_t length,char hash[65]){int out=openat(dir,name,O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600);if(out<0)return false;unsigned char buffer[65536];uint64_t left=length;bool ok=true;while(left){size_t take=left<sizeof(buffer)?(size_t)left:sizeof(buffer);ssize_t n=recv(sock,buffer,take,0);if(n<0&&errno==EINTR)continue;if(n<=0||!store_write_all(out,buffer,(size_t)n)){ok=false;break;}left-=(size_t)n;}if(ok)ok=fsync(out)==0;close(out);if(ok){out=openat(dir,name,O_RDONLY|O_NOFOLLOW);ok=out>=0&&ft_hash_fd(out,hash);if(out>=0)close(out);}if(!ok)unlinkat(dir,name,0);return ok;}
static void store_block_put(int fd,int dir,cJSON*m,uint64_t index,uint64_t length,const char*headers){uint64_t size=store_num(m,"size"),count=(size+SE9_FT_BLOCK-1)/SE9_FT_BLOCK;if(strcmp(ft_string(m,"direction"),"upload")||index>=count||strcmp(ft_string(m,"state"),"transferring")){store_reply(fd,409,"TRANSFER_STATE","invalid upload state",NULL);return;}uint64_t required=size-index*SE9_FT_BLOCK;if(required>SE9_FT_BLOCK)required=SE9_FT_BLOCK;char expected[65];if(length!=required||!store_header(headers,"X-SE9-Block-SHA256",expected,sizeof(expected))||!ft_hex(expected,32)){store_reply(fd,400,"INVALID_BLOCK","invalid block length or hash",NULL);return;}char tmp[80],name[48],random[17],actual[65];ft_random_hex(random,8);snprintf(tmp,sizeof(tmp),"block-%" PRIu64 ".%s.tmp",index,random);snprintf(name,sizeof(name),"block-%" PRIu64,index);if(!store_receive_block(fd,dir,tmp,length,actual)){store_reply(fd,507,"NO_SPACE","cannot persist block",NULL);return;}if(strcmp(expected,actual)){unlinkat(dir,tmp,0);store_reply(fd,409,"HASH_MISMATCH","block hash mismatch",NULL);return;}cJSON*blocks=cJSON_GetObjectItemCaseSensitive(m,"blocks");cJSON*previous=cJSON_GetArrayItem(blocks,(int)index);if(cJSON_IsString(previous)){unlinkat(dir,tmp,0);if(strcmp(previous->valuestring,actual)){store_reply(fd,409,"BLOCK_CONFLICT","block already committed",NULL);return;}}else{if(renameat(dir,tmp,dir,name)!=0||fsync(dir)!=0){unlinkat(dir,tmp,0);store_reply(fd,500,"IO_ERROR","block rename failed",NULL);return;}cJSON_ReplaceItemInArray(blocks,(int)index,cJSON_CreateString(actual));if(!store_save(dir,"manifest.json",m)){store_reply(fd,500,"IO_ERROR","manifest sync failed",NULL);return;}}store_reply(fd,200,"0","success",store_view(m,0,false));}
static void store_block_get(int fd,int dir,cJSON*m,uint64_t index){uint64_t size=store_num(m,"size"),count=(size+SE9_FT_BLOCK-1)/SE9_FT_BLOCK;if(strcmp(ft_string(m,"direction"),"download")||index>=count||!strcmp(ft_string(m,"state"),"cancelled")){store_reply(fd,409,"TRANSFER_STATE","invalid download state",NULL);return;}int input=openat(dir,"snapshot",O_RDONLY|O_NOFOLLOW);if(input<0){store_reply(fd,410,"SNAPSHOT_EXPIRED","snapshot unavailable",NULL);return;}uint64_t length=size-index*SE9_FT_BLOCK;if(length>SE9_FT_BLOCK)length=SE9_FT_BLOCK;unsigned char*buffer=malloc((size_t)length);size_t got=0;bool ok=buffer!=NULL;while(ok&&got<length){ssize_t n=pread(input,buffer+got,(size_t)length-got,(off_t)(index*SE9_FT_BLOCK+got));if(n<0&&errno==EINTR)continue;if(n<=0){ok=false;break;}got+=(size_t)n;}close(input);char hash[65];if(!ok||!ft_sha256(buffer,got,hash)){free(buffer);store_reply(fd,500,"IO_ERROR","snapshot read failed",NULL);return;}char header[512];int n=snprintf(header,sizeof(header),"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: %zu\r\nX-SE9-Block-SHA256: %s\r\nConnection: close\r\n\r\n",got,hash);store_send_all(fd,header,(size_t)n);store_send_all(fd,buffer,got);free(buffer);}
static void store_download_ack(int fd,int dir,cJSON*m,uint64_t index,cJSON*in){uint64_t size=store_num(m,"size"),count=(size+SE9_FT_BLOCK-1)/SE9_FT_BLOCK;if(strcmp(ft_string(m,"direction"),"download")||index>=count||!ft_hex(ft_string(in,"sha256"),32)||strcmp(ft_string(m,"state"),"transferring")){store_reply(fd,409,"TRANSFER_STATE","invalid download acknowledgement",NULL);return;}uint64_t length=size-index*SE9_FT_BLOCK;if(length>SE9_FT_BLOCK)length=SE9_FT_BLOCK;unsigned char*data=malloc((size_t)length);int input=openat(dir,"snapshot",O_RDONLY|O_NOFOLLOW);size_t used=0;bool ok=data&&input>=0;while(ok&&used<length){ssize_t n=pread(input,data+used,(size_t)length-used,(off_t)(index*SE9_FT_BLOCK+used));if(n<0&&errno==EINTR)continue;if(n<=0){ok=false;break;}used+=(size_t)n;}if(input>=0)close(input);char hash[65];if(!ok||!ft_sha256(data,used,hash)||strcmp(hash,ft_string(in,"sha256"))){free(data);store_reply(fd,409,"HASH_MISMATCH","snapshot block verification failed",NULL);return;}free(data);cJSON*blocks=cJSON_GetObjectItemCaseSensitive(m,"blocks");cJSON_ReplaceItemInArray(blocks,(int)index,cJSON_CreateString(hash));if(!store_save(dir,"manifest.json",m)){store_reply(fd,500,"IO_ERROR","acknowledgement persistence failed",NULL);return;}store_reply(fd,200,"0","success",store_view(m,0,false));}
static void store_complete(int fd,int dir,cJSON*m,cJSON*in){uint64_t provided=0;if(!ft_u64(in,"size",&provided)||provided!=store_num(m,"size")||strcmp(ft_string(in,"sha256"),ft_string(m,"sha256"))){store_reply(fd,409,"HASH_MISMATCH","completion metadata mismatch",NULL);return;}if(!strcmp(ft_string(m,"state"),"completed")){store_reply(fd,200,"0","success",store_view(m,0,false));return;}if(!strcmp(ft_string(m,"state"),"cancelled")){store_reply(fd,409,"TRANSFER_STATE","transfer cancelled",NULL);return;}
 cJSON*required_blocks=cJSON_GetObjectItemCaseSensitive(m,"blocks");for(int i=0;i<cJSON_GetArraySize(required_blocks);i++)if(!cJSON_IsString(cJSON_GetArrayItem(required_blocks,i))){store_reply(fd,409,"MISSING_BLOCKS","transfer incomplete",NULL);return;}if(!strcmp(ft_string(m,"direction"),"upload")){cJSON*blocks=required_blocks;
  bool recovering=!strcmp(ft_string(m,"state"),"committing");int merged=openat(dir,"merged",recovering?(O_RDONLY|O_NOFOLLOW):(O_RDWR|O_CREAT|O_TRUNC|O_NOFOLLOW),0600);bool ok=merged>=0;for(int i=0;!recovering&&ok&&i<cJSON_GetArraySize(blocks);i++){char name[48];snprintf(name,sizeof(name),"block-%d",i);int input=openat(dir,name,O_RDONLY|O_NOFOLLOW);ok=input>=0&&store_copy(input,merged);if(input>=0)close(input);}char hash[65];if(ok)ok=fsync(merged)==0&&ft_hash_fd(merged,hash)&&!strcmp(hash,ft_string(m,"sha256"));if(!ok){if(merged>=0)close(merged);unlinkat(dir,"merged",0);store_reply(fd,409,"HASH_MISMATCH","merged file verification failed",NULL);return;}
  char leaf[256];int parent=store_parent(ft_string(m,"path"),false,leaf);if(parent<0){close(merged);store_reply(fd,400,"PATH_DENIED","destination unavailable",NULL);return;}store_string(m,"state","committing");if(!store_save(dir,"manifest.json",m)){close(parent);close(merged);store_reply(fd,500,"IO_ERROR","commit intent failed",NULL);return;}
  if(linkat(dir,"merged",parent,leaf,0)!=0){struct stat source,target;bool ours=fstat(merged,&source)==0&&fstatat(parent,leaf,&target,AT_SYMLINK_NOFOLLOW)==0&&source.st_dev==target.st_dev&&source.st_ino==target.st_ino;if(!ours){close(parent);close(merged);store_reply(fd,409,"FILE_EXISTS","destination exists",NULL);return;}}
  if(fsync(parent)!=0){close(parent);close(merged);store_reply(fd,500,"IO_ERROR","destination sync failed",NULL);return;}close(parent);close(merged);
 }
 store_string(m,"state","completed");if(!store_save(dir,"manifest.json",m)){store_reply(fd,500,"IO_ERROR","completion persistence failed",NULL);return;}if(!strcmp(ft_string(m,"direction"),"upload")){unlinkat(dir,"merged",0);cJSON*blocks=cJSON_GetObjectItemCaseSensitive(m,"blocks");for(int i=0;i<cJSON_GetArraySize(blocks);i++){char name[48];snprintf(name,sizeof(name),"block-%d",i);unlinkat(dir,name,0);}fsync(dir);}store_reply(fd,200,"0","success",store_view(m,0,false));}
bool se9_transfer_handle(int fd,const char*method,const char*target,const char*headers,int64_t length){if(strncmp(target,"/api/v2/transfers",17)||!(target[17]==0||target[17]=='/'||target[17]=='?'))return false;char proxy[129],user[129],device[129];if(ft_store<0||!ft_proxy[0]||!store_header(headers,"X-Agent-Proxy-Token",proxy,sizeof(proxy))||!ft_constant_equal(proxy,ft_proxy)||!store_header(headers,"X-SE9-User-ID",user,sizeof(user))||!store_identity(user)||!store_header(headers,"X-SE9-Device-ID",device,sizeof(device))||!store_identity(device)){store_reply(fd,401,"RTC_AUTH_FAILED","trusted transfer principal required",NULL);return true;}if(length<0||length>SE9_FT_BLOCK){store_reply(fd,413,"INVALID_BLOCK","request too large",NULL);return true;}
 const char *suffix=target+17;if(!*suffix){if(strcmp(method,"POST")){store_reply(fd,405,"METHOD_NOT_ALLOWED","POST required",NULL);return true;}cJSON*in=store_json_fd(fd,(uint64_t)length);if(!in){store_reply(fd,400,"INVALID_TRANSFER","invalid JSON",NULL);return true;}store_start(fd,user,device,in);cJSON_Delete(in);return true;}
 if(*suffix!='/'){store_reply(fd,404,"TRANSFER_NOT_FOUND","invalid task route",NULL);return true;}suffix++;char id[33];size_t idlen=strcspn(suffix,"/?");if(idlen!=32){store_reply(fd,404,"TRANSFER_NOT_FOUND","invalid task",NULL);return true;}memcpy(id,suffix,32);id[32]=0;if(!ft_hex(id,16)){store_reply(fd,404,"TRANSFER_NOT_FOUND","invalid task",NULL);return true;}suffix+=32;
 int dir=openat(ft_store,id,O_RDONLY|O_DIRECTORY|O_NOFOLLOW);if(dir<0){store_reply(fd,404,"TRANSFER_NOT_FOUND","task not found",NULL);return true;}int lock=openat(dir,"task.lock",O_RDWR|O_NOFOLLOW);if(lock<0||flock(lock,LOCK_EX)!=0){if(lock>=0)close(lock);close(dir);store_reply(fd,500,"IO_ERROR","task lock failed",NULL);return true;}cJSON*m=store_load(dir,"manifest.json");char resume[65],hash[65];if(!m||strcmp(ft_string(m,"userId"),user)||strcmp(ft_string(m,"deviceId"),device)||!store_header(headers,"X-SE9-Resume-Token",resume,sizeof(resume))||!ft_sha256(resume,strlen(resume),hash)||!ft_constant_equal(hash,ft_string(m,"resumeTokenHash"))){store_reply(fd,403,"RTC_AUTH_FAILED","task credentials invalid",NULL);goto done;}if(store_num(m,"expiresAt")<(uint64_t)time(NULL)){store_reply(fd,410,"TRANSFER_EXPIRED","task expired",NULL);goto done;}
 if((!*suffix||!strncmp(suffix,"?cursor=",8))&&!strcmp(method,"GET")){uint64_t cursor=0;if(*suffix){char*end=NULL;errno=0;cursor=strtoull(suffix+8,&end,10);if(errno||end==suffix+8||*end){store_reply(fd,400,"INVALID_CURSOR","invalid cursor",NULL);goto done;}}store_reply(fd,200,"0","success",store_view(m,cursor,false));goto done;}
 if(!strcmp(suffix,"/resume")&&!strcmp(method,"POST")){cJSON*in=store_json_fd(fd,(uint64_t)length);if(!in){store_reply(fd,400,"INVALID_TRANSFER","invalid JSON",NULL);goto done;}bool valid=strcmp(ft_string(m,"direction"),"download")||!strcmp(ft_string(in,"sourceVersion"),ft_string(m,"sourceVersion"));cJSON_Delete(in);if(!valid){store_reply(fd,409,"SOURCE_CHANGED","snapshot version mismatch",NULL);goto done;}uint64_t epoch=store_num(m,"epoch");if(epoch>=UINT32_MAX||!strcmp(ft_string(m,"state"),"cancelled")){store_reply(fd,409,"TRANSFER_STATE","cannot resume",NULL);goto done;}store_uint(m,"epoch",epoch+1);if(!store_save(dir,"manifest.json",m)){store_reply(fd,500,"IO_ERROR","epoch persistence failed",NULL);goto done;}store_reply(fd,200,"0","success",store_view(m,0,false));goto done;}
 char epoch_text[32],*end=NULL;if(!store_header(headers,"X-SE9-Epoch",epoch_text,sizeof(epoch_text))){store_reply(fd,409,"STALE_EPOCH","epoch required",NULL);goto done;}errno=0;unsigned long long epoch=strtoull(epoch_text,&end,10);if(errno||end==epoch_text||*end||epoch!=store_num(m,"epoch")){store_reply(fd,409,"STALE_EPOCH","stale writer",NULL);goto done;}
 if(!strncmp(suffix,"/blocks/",8)){const char*num=suffix+8;errno=0;uint64_t index=strtoull(num,&end,10);if(errno||end==num||(*end&&strcmp(end,"/ack"))||*num<'0'||*num>'9'){store_reply(fd,400,"INVALID_BLOCK","invalid index",NULL);goto done;}if(!strcmp(end,"/ack")&&!strcmp(method,"POST")){cJSON*in=store_json_fd(fd,(uint64_t)length);if(in){store_download_ack(fd,dir,m,index,in);cJSON_Delete(in);}else store_reply(fd,400,"INVALID_TRANSFER","invalid JSON",NULL);goto done;}if(*end){store_reply(fd,405,"METHOD_NOT_ALLOWED","invalid acknowledgement method",NULL);goto done;}if(!strcmp(method,"PUT"))store_block_put(fd,dir,m,index,(uint64_t)length,headers);else if(!strcmp(method,"GET"))store_block_get(fd,dir,m,index);else store_reply(fd,405,"METHOD_NOT_ALLOWED","invalid block method",NULL);goto done;}
 if(!strcmp(suffix,"/complete")&&!strcmp(method,"POST")){cJSON*in=store_json_fd(fd,(uint64_t)length);if(!in){store_reply(fd,400,"INVALID_TRANSFER","invalid JSON",NULL);goto done;}store_complete(fd,dir,m,in);cJSON_Delete(in);goto done;}
 if(!*suffix&&!strcmp(method,"DELETE")){if(!strcmp(ft_string(m,"state"),"committing")){store_reply(fd,409,"TRANSFER_STATE","publication in progress; retry completion",NULL);goto done;}if(strcmp(ft_string(m,"state"),"completed")){store_string(m,"state","cancelled");if(!store_save(dir,"manifest.json",m)){store_reply(fd,500,"IO_ERROR","cancel persistence failed",NULL);goto done;}}store_reply(fd,200,"0","success",store_view(m,0,false));goto done;}
 store_reply(fd,404,"TRANSFER_NOT_FOUND","route not found",NULL);
done:cJSON_Delete(m);flock(lock,LOCK_UN);close(lock);close(dir);return true;
}
